import type { Metadata } from "next";
import { db } from "@/lib/db";
import { Reveal } from "@/components/marketing/Reveal";
import { PricingGrid } from "@/components/marketing/PricingGrid";
import { DeployCatalog, type CatalogGroup } from "@/components/marketing/DeployCatalog";
import { StatCounter } from "@/components/marketing/StatCounter";
import { Section, SectionTitle, PageHero } from "@/components/marketing/primitives";
import { FeatureCard, CtaBand } from "@/components/marketing/sections";
import {
  IconNvme,
  IconTerminal,
  IconBackup,
  IconShield,
  IconServer,
  IconGauge,
  IconScale,
  IconGlobe,
  IconLock,
  IconNetwork,
  IconDisk,
} from "@/components/marketing/icons";

export const dynamic = "force-dynamic";

export const metadata: Metadata = {
  title: "VPS Hosting — Nxeon",
  description:
    "High-performance NVMe cloud VPS with full root access, a dedicated IPv4, snapshots, backups, DDoS protection, and one-click apps. Deployed from Singapore in under a minute.",
};

const CATEGORY_LABELS: Record<string, string> = {
  PLAIN_OS: "Operating systems",
  CONTROL_PANEL: "Control panels",
  APPLICATION: "One-click apps",
};

const FALLBACK: Record<string, string[]> = {
  PLAIN_OS: ["Ubuntu 24.04", "Debian 13", "AlmaLinux 9", "Rocky Linux 9", "Fedora"],
  CONTROL_PANEL: ["cPanel", "Plesk", "CyberPanel", "Webmin", "CloudPanel", "aaPanel", "HestiaCP"],
  APPLICATION: ["Docker", "WordPress", "Nextcloud", "Ghost", "n8n", "PostgreSQL"],
};

/** The four headline reasons to pick a Nxeon VPS. */
const PILLARS = [
  {
    icon: <IconNvme />,
    title: "NVMe on ZFS",
    body: "Every plan runs on enterprise NVMe SSD in a ZFS mirror for real IOPS — fast boots, fast builds, fast databases, and self-healing data integrity.",
  },
  {
    icon: <IconTerminal />,
    title: "Full root access",
    body: "Complete control over your server via SSH. Install anything, tune the kernel, run containers — it is your box, not a locked-down sandbox.",
  },
  {
    icon: <IconGlobe />,
    title: "Dedicated IPv4 by default",
    body: "Every server ships with its own dedicated IPv4 address — no shared NAT, no noisy neighbours. Run your own reverse DNS and services directly.",
  },
  {
    icon: <IconShield />,
    title: "DDoS protection & firewall",
    body: "Always-on volumetric mitigation at the network edge plus a managed firewall on every server, so an attack on one tenant never touches yours.",
  },
];

/** Platform features that used to go unmarketed — surfaced as a spec grid. */
const CAPABILITIES = [
  { icon: <IconTerminal />, title: "noVNC web console", body: "A full browser console straight to the hypervisor — get in and fix things even when SSH or the network is down." },
  { icon: <IconBackup />, title: "Automatic backups", body: "Scheduled backups stream to a separate storage pool, so your data survives even a full host failure." },
  { icon: <IconDisk />, title: "Instant snapshots", body: "Capture a point-in-time image before a risky change and roll back in seconds if it goes sideways." },
  { icon: <IconNetwork />, title: "IPv6 ready", body: "Native IPv6 alongside your dedicated IPv4, so you are ready for modern networking out of the box." },
  { icon: <IconScale />, title: "One-click resize", body: "Scale vCPU, RAM, and disk up as you grow — straight from the dashboard, no rebuild required." },
  { icon: <IconLock />, title: "Two-factor auth", body: "Protect your account with TOTP 2FA, so a leaked password alone can never reach your servers." },
  { icon: <IconLock />, title: "SSH key management", body: "Store and manage your SSH keys once, then drop them onto any new server at deploy time." },
  { icon: <IconGauge />, title: "Real-time metrics", body: "Live CPU, memory, disk, and network graphs from the hypervisor — spot pressure before it becomes an incident." },
];

const FAQ = [
  { q: "How fast is provisioning?", a: "Servers are automated end-to-end and typically deploy in under 60 seconds — NVMe clone, cloud-init, IP allocation, and firewall rules all applied automatically." },
  { q: "Do I get full root access?", a: "Yes. Every VPS gives you complete root over SSH plus a dedicated IPv4 address. Install anything, tune the kernel, and run whatever you like." },
  { q: "Can I resize later?", a: "Absolutely. Bump vCPU, RAM, and disk from the dashboard as your workload grows — no need to rebuild from scratch." },
