];

export default async function VpsPage() {
  const [plans, templates] = await Promise.all([
    db.plan.findMany({ where: { active: true }, orderBy: { sortOrder: "asc" } }),
    db.osTemplate.findMany({ where: { active: true }, orderBy: { sortOrder: "asc" } }),
  ]);

  const OS_FAMILY_LABEL: Record<string, string> = {
    ubuntu: "Ubuntu", debian: "Debian", almalinux: "AlmaLinux", rocky: "Rocky Linux",
    fedora: "Fedora", centos: "CentOS", arch: "Arch Linux", alpine: "Alpine", opensuse: "openSUSE",
  };
  const byCat = (cat: string) => {
    const list = templates.filter((t) => t.category === cat);
    if (cat === "PLAIN_OS") {
      const seen = new Set<string>();
      const fams: string[] = [];
      for (const t of list) {
        const fam = (t.family || t.name).toLowerCase();
        if (seen.has(fam)) continue;
        seen.add(fam);
        fams.push(OS_FAMILY_LABEL[fam] ?? (t.family ? t.family[0].toUpperCase() + t.family.slice(1) : t.name));
      }
      return fams.length ? fams : FALLBACK[cat];
    }
    const live = list.map((t) => t.name);
    return live.length ? live : FALLBACK[cat];
  };
  const groups: CatalogGroup[] = (["PLAIN_OS", "CONTROL_PANEL", "APPLICATION"] as const).map((cat) => ({
    key: cat,
    label: CATEGORY_LABELS[cat],
    items: byCat(cat),
  }));
  const totalImages = groups.reduce((n, g) => n + g.items.length, 0);

  return (
    <>
      <PageHero
        eyebrow="VPS Hosting"
        title="Cloud VPS that feels"
        highlight="instant"
        sub={`High-performance virtual servers on enterprise NVMe, with full root access, a dedicated IPv4, snapshots, backups, and ${totalImages}+ one-click images — deployed from Singapore in under a minute.`}
        primary={{ label: "Deploy your VPS", href: "/register" }}
        secondary={{ label: "View pricing", href: "#pricing" }}
      />

      {/* Trust stat strip */}
      <Section tone="panel" size="sm">
        <div className="grid gap-8 sm:grid-cols-2 lg:grid-cols-4">
          <StatCounter value={47} suffix="s" label="Median deploy time" />
          <StatCounter value={99.9} decimals={1} suffix="%" label="Uptime SLA" />
          <StatCounter value={totalImages} suffix="+" label="One-click images" />
          <StatCounter value={100} suffix="%" label="Root access" />
        </div>
      </Section>

      {/* Value pillars */}
      <Section size="lg">
        <SectionTitle
          eyebrow="Why Nxeon VPS"
          title="A real server, not a sandbox"
          sub="The smallest box gets the same platform as the largest — you only choose how much horsepower you need."
        />
        <div className="mt-12 grid gap-5 sm:grid-cols-2 lg:grid-cols-4">
          {PILLARS.map((f, i) => (
            <FeatureCard key={f.title} icon={f.icon} title={f.title} delay={(i % 4) * 60}>
              {f.body}
            </FeatureCard>
          ))}
        </div>
      </Section>

      {/* Deploy catalog */}
      <Section tone="panel" size="lg">
        <SectionTitle
          eyebrow="Deploy anything"
          title="Your stack, ready on first boot"
          sub={`Pick from ${totalImages}+ images across operating systems, control panels, and one-click apps — then customise everything with full root access.`}
        />
        <Reveal className="mt-12">
          <DeployCatalog groups={groups} />
        </Reveal>
      </Section>

      {/* Capability / spec grid — previously unmarketed features */}
      <Section size="lg">
        <SectionTitle
          eyebrow="Under the hood"
          title="More in the box than you'd expect"
          sub="Every account and every server comes with the tooling to run, protect, and recover your workloads — no add-ons, no upsells."
        />
        <div className="mt-12 grid gap-5 sm:grid-cols-2 lg:grid-cols-4">
          {CAPABILITIES.map((f, i) => (
            <FeatureCard key={f.title} icon={f.icon} title={f.title} delay={(i % 4) * 60}>
              {f.body}
            </FeatureCard>
          ))}
        </div>
      </Section>

      {/* Pricing */}
      <Section tone="panel" size="lg" id="pricing">
        <SectionTitle
          eyebrow="Pricing"
          title="Pick the box that fits"
          sub="Each plan shows what it is great for, generated from its specs — so you can self-select with confidence. Pay monthly, cancel anytime."
        />
        <div className="mt-6 flex justify-center">
          <span className="inline-flex items-center gap-2 rounded-full border border-emerald-500/25 bg-emerald-500/10 px-3.5 py-1.5 text-sm font-medium text-emerald-300">
            <span className="flex h-1.5 w-1.5 rounded-full bg-emerald-400 animate-pulse-dot" />
            Save up to 20% on 3-year terms with annual billing
          </span>
        </div>
        <Reveal className="mt-8">
          <PricingGrid plans={plans} />
        </Reveal>
      </Section>

      {/* FAQ */}
      <Section size="md">
        <SectionTitle eyebrow="FAQ" title="Questions, answered" />
        <div className="mx-auto mt-10 max-w-3xl space-y-4">
          {FAQ.map((f, i) => (
            <Reveal key={f.q} delay={i * 40}>
              <div className="card">
                <h3 className="text-base font-semibold text-white">{f.q}</h3>
                <p className="mt-2 text-sm leading-relaxed text-slate-400">{f.a}</p>
              </div>
            </Reveal>
          ))}
        </div>
      </Section>

      <Section tone="deep" size="lg">
        <CtaBand />
      </Section>
    </>
  );
}

